def write_dataset() -> tuple[list[dict], list[dict]]:
    records: list[dict] = []
    now = datetime(2026, 10, 8, 12, 0, 0)
    identifier = 1
    for category, scenarios in CATEGORIES:
        for scenario_index, scenario in enumerate(scenarios):
            (
                project,
                service,
                deployment_stage,
                severity,
                root_cause,
                impact,
                resolution,
                messages,
            ) = scenario
            assert service in PROJECTS[project], f"Invalid service association: {project} / {service}"
            for sequence_index, raw_log in enumerate(messages):
                timestamp = now + timedelta(minutes=identifier - 1)
                canonical = normalize_log(
                    raw_log,
                    project=project,
                    service=service,
                    deployment_stage=deployment_stage,
                )
                records.append(
                    {
                        "id": f"DEP-{identifier:04d}",
                        "project": project,
                        "service": service,
                        "deployment_stage": deployment_stage,
                        "timestamp": timestamp.isoformat(timespec="seconds"),
                        "level": ["WARN", "ERROR", "ERROR", "ERROR", "ERROR"][sequence_index],
                        "raw_log": raw_log,
                        "normalized_message": canonical["message"],
                        "incident_type": category,
                        "severity": severity,
                        "probable_root_cause": root_cause,
                        "troubleshooting_steps": TROUBLESHOOTING_STEPS[category],
                        "expected_resolution": resolution,
                        "metadata": {
                            "scenario_id": f"{category.lower().replace('/', '-').replace(' ', '-')}-{scenario_index + 1}",
                            "sequence_index": sequence_index + 1,
                            "impact": impact,
                        },
                    }
                )
                identifier += 1

    test_cases = [
        {
            "id": f"CASE-{index:03d}",
            "query": {
                "project": project,
                "service": service,
                "deployment_stage": stage,
                "raw_log": raw_log,
            },
            "expected": {"incident_type": category, "probable_root_cause": root_cause},
        }
        for index, (project, service, stage, raw_log, category, root_cause) in enumerate(TEST_CASES, 1)
    ]
    return records, test_cases


def main() -> None:
    records, test_cases = write_dataset()
    fields = list(records[0])
    (DATA_DIR / "deployment_logs.json").write_text(
        json.dumps(records, indent=2, ensure_ascii=False) + "\n",
        encoding="utf-8",
    )
    with (DATA_DIR / "deployment_logs.csv").open("w", encoding="utf-8-sig", newline="") as stream:
        writer = csv.DictWriter(stream, fieldnames=fields)
        writer.writeheader()
        for record in records:
            writer.writerow(
                {
                    **record,
                    "troubleshooting_steps": json.dumps(record["troubleshooting_steps"], ensure_ascii=False),
                    "metadata": json.dumps(record["metadata"], ensure_ascii=False),
                }
            )
    (DATA_DIR / "test_cases.json").write_text(
        json.dumps(test_cases, indent=2, ensure_ascii=False) + "\n",
        encoding="utf-8",
    )
    category_counts = {
        category: sum(record["incident_type"] == category for record in records)
        for category, _ in CATEGORIES
    }
    print(json.dumps({
        "records": len(records),
        "test_cases": len(test_cases),
        "categories": category_counts,
        "projects": sorted({record["project"] for record in records}),
        "services": len({(record["project"], record["service"]) for record in records}),
    }, indent=2))


if __name__ == "__main__":
    main()
